import {I18N} from '@gravity-ui/i18n';
import type {I18NFn} from '@gravity-ui/i18n';
import {configure, useLang} from '@gravity-ui/uikit';

import en from './keysets/en.json';
import ru from './keysets/ru.json';

export const LANGS = ['en', 'ru'] as const;
export type Lang = (typeof LANGS)[number];

export const DEFAULT_LANG: Lang = 'en';
const STORAGE_KEY = 'app-lang';

export function isLang(value: unknown): value is Lang {
    return typeof value === 'string' && (LANGS as readonly string[]).includes(value);
}

// Application string catalog. uikit keeps its own I18N instance for component strings;
// both are driven by the same `configure({lang})` call in `setLang` below.
const i18nInstance = new I18N({
    lang: DEFAULT_LANG,
    fallbackLang: DEFAULT_LANG,
    data: {en, ru},
});

type TypedI18n = I18NFn<typeof en>;

/** Typed translation function for the `app` keyset: `t('title')`. */
export const t = (i18nInstance.i18n as TypedI18n).bind(i18nInstance, 'app');

function readStoredLang(): Lang | null {
    try {
        const stored = window.localStorage.getItem(STORAGE_KEY);
        return isLang(stored) ? stored : null;
    } catch {
        return null;
    }
}

function detectBrowserLang(): Lang {
    const candidate = window.navigator.language?.slice(0, 2).toLowerCase();
    return isLang(candidate) ? candidate : DEFAULT_LANG;
}

/**
 * Switch the interface language: app strings, uikit component strings
 * (via `configure`), the document `lang` attribute, and the persisted choice.
 */
export function setLang(lang: Lang) {
    i18nInstance.setLang(lang);
    configure({lang, fallbackLang: DEFAULT_LANG});
    document.documentElement.lang = lang;
    try {
        window.localStorage.setItem(STORAGE_KEY, lang);
    } catch {
        // storage is unavailable (private mode, quota) — language still switches for this session
    }
}

/** Call once before the first render. */
export function initLang() {
    setLang(readStoredLang() ?? detectBrowserLang());
}

/**
 * Current interface language. Backed by uikit's language store, so every
 * component using this hook re-renders when `setLang` is called.
 */
export function useAppLang(): Lang {
    const {lang} = useLang();
    return isLang(lang) ? lang : DEFAULT_LANG;
}
EOF
cat > src/LanguageSwitcher.tsx <<'EOF'
import {SegmentedRadioGroup} from '@gravity-ui/uikit';

import {LANGS, setLang, t, useAppLang} from './i18n';
import type {Lang} from './i18n';

export function LanguageSwitcher() {
    const lang = useAppLang();

    return (
        <SegmentedRadioGroup<Lang>
            size="m"
            value={lang}
            onUpdate={setLang}
            aria-label={t('label_language')}
        >
            {LANGS.map((value) => (
                <SegmentedRadioGroup.Option key={value} value={value}>
                    {t(`lang_${value}`)}
                </SegmentedRadioGroup.Option>
            ))}
        </SegmentedRadioGroup>
    );
}
EOF
cat > src/App.tsx <<'EOF'
import {useState} from 'react';
import {Button, Card, Flex, Pagination, Table, Text} from '@gravity-ui/uikit';

import {LanguageSwitcher} from './LanguageSwitcher';
import {t, useAppLang} from './i18n';

type Row = {id: string; name: string; status: string};

export function App() {
    const lang = useAppLang();
    const [count, setCount] = useState(0);
    const [page, setPage] = useState(1);

    const rows: Row[] = [];
    const columns = [
        {id: 'name', name: t('column_name')},
        {id: 'status', name: t('column_status')},
    ];

    return (
        <Flex direction="column" gap={6} style={{maxWidth: 960, margin: '0 auto', padding: 'var(--g-spacing-6)'}}>
            <Flex alignItems="center" justifyContent="space-between" gap={4} wrap>
                <Text as="h1" variant="header-1" style={{flex: 1, minWidth: 0, margin: 0}}>
                    {t('title')}
                </Text>
                <div style={{flexShrink: 0}}>
                    <LanguageSwitcher />
                </div>
            </Flex>

            <Text variant="body-2" color="secondary">
                {t('subtitle')}
            </Text>

            <Card type="container" view="outlined" spacing={{p: 5}}>
                <Flex direction="column" gap={4}>
                    <Text variant="subheader-2">{t('section_app-strings')}</Text>
                    <Text variant="body-1">{t('label_current-language', {lang: t(`lang_${lang}`)})}</Text>
                    <Text variant="body-1">{t('label_items', {count})}</Text>
                    <Flex gap={2}>
                        <Button view="action" onClick={() => setCount((value) => value + 1)}>
                            {t('button_add-item')}
                        </Button>
                        <Button view="normal" onClick={() => setCount(0)}>
                            {t('button_reset')}
                        </Button>
                    </Flex>
                </Flex>
            </Card>

            <Card type="container" view="outlined" spacing={{p: 5}}>
                <Flex direction="column" gap={4}>
                    <Text variant="subheader-2">{t('section_uikit-strings')}</Text>
                    <Text variant="body-1" color="secondary">
                        {t('hint_uikit-strings')}
                    </Text>
                    <Pagination
                        page={page}
                        pageSize={10}
                        total={50}
                        compact={false}
                        onUpdate={(nextPage) => setPage(nextPage)}
                    />
                    <Table data={rows} columns={columns} />
                </Flex>
            </Card>
        </Flex>
    );
}
